package com.dvopenlabs.freedom.camera;

import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.provider.Settings;
import android.net.Uri;
import android.view.*;
import android.widget.*;

/** Configure first, preview in-app, then separately choose overlay/system access. No fetch on open. */
public final class CameraActivity extends Activity {
    LinearLayout body;CameraPlayer player;boolean onHome;final Handler timeout=new Handler(Looper.getMainLooper());
    android.content.SharedPreferences prefs(){return getSharedPreferences("camera",0);}
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(0xfff3f6fc);t.setTextSize(size);t.setTypeface(getResources().getFont(R.font.outfit));t.setPadding(0,dp(8),0,dp(12));return t;}
    void page(String title,String help){onHome=false;body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(40),dp(28),dp(40),dp(28));body.addView(text(title,28));body.addView(text(help,17));ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);}
    void button(String label,Runnable action){TextView t=text(label,18);t.setFocusable(true);t.setClickable(true);t.setMinHeight(dp(52));t.setPadding(dp(16),dp(14),dp(16),dp(14));t.setBackgroundResource(R.drawable.freedom_action);t.setTextColor(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_focused},new int[0]},new int[]{0xff182334,0xfff3f6fc}));t.setOnClickListener(v->action.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);body.addView(t,lp);if(body.getChildCount()==3)t.requestFocus();}
    EditText field(String name,String value,boolean secret){body.addView(text(name,16));EditText e=new EditText(this);e.setText(value);e.setTextColor(-1);e.setSingleLine(true);e.setSaveEnabled(false);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(secret?android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD:android.text.InputType.TYPE_TEXT_VARIATION_URI));body.addView(e,new LinearLayout.LayoutParams(-1,dp(56)));return e;}
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);home();}
    void home(){release();page("DV Freedom Camera","Optional personal camera viewing. Nothing connects on open. Configure HTTPS HLS/MP4, or private-LAN RTSP-over-TCP. No doorbell monitoring, recording, audio, boot start or Accessibility. Overlay and notification posting are separate Android choices.");
        button(prefs().getString("url","").isEmpty()?"Configure a camera":"Change camera source",this::configure);
        button("Preview inside this app",()->{if(!configured())return;stopService(new Intent(this,CameraOverlay.class));preview();});
        button("Show silent corner window",()->{if(!configured())return;if(!Settings.canDrawOverlays(this)||Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){message("Review separate overlay/notification access below before starting. Nothing was enabled.");return;}try{startForegroundService(new Intent(this,CameraOverlay.class));message("Window requested. It stops on timeout, screen-off or Stop. Decoder/HDMI compatibility varies.");}catch(RuntimeException denied){message("Android refused the window; use in-app preview.");}});
        button("Stop camera window",()->{stopService(new Intent(this,CameraOverlay.class));message("Camera window stopped");});
        button("Review overlay access in Android settings",()->new AlertDialog.Builder(this).setTitle("Allow a small camera window?").setMessage("Android draw-over-other-apps access is broad. This app uses a silent, non-touchable corner window with Stop and a 15-minute maximum. Installation does not enable it.").setPositiveButton("Open system choice",(d,n)->{try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(RuntimeException unavailable){message("Use Apps → Special app access on your TV");}}).setNegativeButton("Cancel",null).show());
        if(Build.VERSION.SDK_INT>=33)button("Review notification posting",()->new AlertDialog.Builder(this).setTitle("Allow a Stop notification?").setMessage("Allows posting this app’s ongoing camera status and Stop control. It does not read other notifications.").setPositiveButton("Ask Android",(d,n)->requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},5)).setNegativeButton("Cancel",null).show());
        button("Forget source and credentials",()->new AlertDialog.Builder(this).setTitle("Forget this camera?").setMessage("Stops the window and removes this app’s saved camera address and credentials.").setPositiveButton("Forget",(d,n)->{stopService(new Intent(this,CameraOverlay.class));prefs().edit().clear().apply();home();}).setNegativeButton("Cancel",null).show());
        button("Open-source notices",this::notices);onHome=true;
    }
    boolean configured(){try{CameraPolicy.url(prefs().getString("url",""));return true;}catch(IllegalArgumentException bad){message("Configure and save your camera first");return false;}}
    void configure(){var p=prefs();page("Your camera source","Credentials remain in this app’s backup-excluded storage. HTTPS validates certificates; redirects and foreign HLS origins are refused. RTSP is unencrypted on your LAN: use a dedicated limited viewer account and never port-forward it. Save does not connect.");EditText url=field("HTTPS HLS/MP4 or private-LAN RTSP URL",p.getString("url",""),false),user=field("Optional viewer username",p.getString("user",""),false),password=field("Optional viewer password",p.getString("password",""),true);Spinner duration=new Spinner(this);duration.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"1 minute","5 minutes","15 minutes"}));int[] minutes={1,5,15};int saved=p.getInt("minutes",5);duration.setSelection(saved==1?0:saved==15?2:1);body.addView(duration);
        button("Save source",()->{try{String address=url.getText().toString().trim(),u=CameraPolicy.credential(user.getText().toString()),pw=CameraPolicy.credential(password.getText().toString());CameraPolicy.url(address);if(u.isEmpty()&&!pw.isEmpty())throw new IllegalArgumentException("Enter a username or clear the password");stopService(new Intent(this,CameraOverlay.class));p.edit().putString("url",address).putString("user",u).putString("password",pw).putInt("minutes",minutes[duration.getSelectedItemPosition()]).apply();home();}catch(IllegalArgumentException invalid){message(invalid.getMessage());}});button("Cancel",this::home);}
    void preview(){page("Camera preview · silent","This view stops when you leave the app. No overlay access is needed; DRM/codec compatibility and network reliability vary.");TextureView view=new TextureView(this);body.addView(view,new LinearLayout.LayoutParams(dp(640),dp(360)));button("Stop preview",this::home);try{var p=prefs();player=new CameraPlayer(this,view,p.getString("url",""),p.getString("user",""),p.getString("password",""),()->{release();message("Camera unavailable. Check source, account, certificate and decoder support.");});timeout.postDelayed(()->{release();message("Camera preview ended");},CameraPolicy.duration(p.getInt("minutes",5)));}catch(RuntimeException bad){release();message("Camera could not start. Check its source and supported format.");}}
    void notices(){page("Open-source notices","DV Freedom Camera uses Media3 and OkHttp with retained dependency notices. No camera image or stream is bundled.");try{for(String file:getAssets().list(""))if(file.endsWith(".txt")){String data;try(java.io.InputStream in=getAssets().open(file)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] bytes=new byte[4096];for(int n;(n=in.read(bytes))>0&&out.size()<200000;)out.write(bytes,0,n);data=out.toString("UTF-8");}body.addView(text(file+"\n"+data,14));}}catch(Exception unavailable){body.addView(text("Source and notices: github.com/DVOpenLabs/dv-freedom-launcher",16));}button("Back",this::home);}
    void message(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
    void release(){timeout.removeCallbacksAndMessages(null);if(player!=null){player.close();player=null;}}
    @Override public void onBackPressed(){if(onHome)super.onBackPressed();else home();}
    @Override public void onPause(){release();super.onPause();}
}
